// Tipos de dominio de PetDesk. Tiempos como ISO 8601 string (UTC).
// Ver docs/PLAN.md para el contexto de arquitectura.

export interface Service {
  id: string;
  name: string;
  durationMin: number;
  priceCents: number;
  upsells: string[]; // nombres de servicios sugeridos tras reservar
}

export interface Client {
  id: string;
  name: string;
  phone: string;
}

export type AppointmentStatus = 'booked' | 'cancelled' | 'completed';

export interface Appointment {
  id: string;
  clientId: string;
  serviceId: string;
  start: string; // ISO
  end: string; // ISO
  status: AppointmentStatus;
}

export interface WaitlistEntry {
  id: string;
  clientId: string;
  serviceId: string;
  windowStart: string; // ISO — inicio de la ventana en que el cliente acepta un hueco
  windowEnd: string; // ISO — fin de la ventana
  createdAt: string; // ISO — usado para orden FIFO del backfill
}

export interface ReminderJob {
  id: string;
  appointmentId: string;
  dueAt: string; // ISO — cuándo debe dispararse el recordatorio
  sent: boolean;
}

export type NotificationKind =
  | 'confirmation'
  | 'upsell'
  | 'backfill_offer'
  | 'reminder';

export interface Notification {
  id: string;
  clientId: string;
  kind: NotificationKind;
  body: string;
  createdAt: string; // ISO
}

export interface Slot {
  start: string; // ISO
  end: string; // ISO
}

// ---- Métricas / Stats (v3 — feature stats dashboard) ----
// Agregaciones calculadas por StatsEngine sobre un rango temporal.

export interface ServiceCount {
  serviceId: string;
  count: number;
}

export interface ClientCount {
  clientId: string;
  count: number;
}

export interface StatsBundle {
  // Rango analizado (incl. start, excl. end)
  rangeStart: string; // ISO
  rangeEnd: string; // ISO

  // Volúmenes (citas en el rango — cualquier estado)
  appointmentsTotal: number;
  appointmentsBooked: number;
  appointmentsCompleted: number;
  appointmentsCancelled: number;

  // Tasas en [0..1]
  cancellationRate: number; // cancelled / total (0 si total=0)
  occupancyRate: number; // citas_no_canceladas_min / minutos_laborables_del_rango (0..1)

  // Tops (ordenados desc por count, máximo 5 cada uno)
  topServicesByBookings: ServiceCount[];
  topServicesByCancellations: ServiceCount[];
  topClientsByVisits: ClientCount[];
}

// Puertos (interfaces) de PetDesk. Los devs implementan/consumen estas interfaces;
// permiten paralelismo (Dev Chat codea contra SchedulerPort sin la implementación de Dev Motor)
// y el swap de infraestructura (InMemoryRepo -> DB, InAppNotifier -> email/SMS) sin tocar la lógica.
// Ver docs/PLAN.md.

import type {
  Appointment,
  Client,
  Notification,
  ReminderJob,
  Service,
  Slot,
  WaitlistEntry,
} from './types';

// Reloj inyectable -> tests deterministas y "avanzar tiempo" en la demo.
export interface Clock {
  now(): Date;
}

// Persistencia. Síncrona para el MVP en memoria; el swap a DB es fase posterior.
export interface Repository {
  // Services
  listServices(): Service[];
  getService(id: string): Service | undefined;
  // Clients
  listClients(): Client[];
  getClient(id: string): Client | undefined;
  saveClient(client: Client): void;
  // Appointments
  listAppointments(): Appointment[];
  getAppointment(id: string): Appointment | undefined;
  saveAppointment(appointment: Appointment): void;
  // Waitlist
  listWaitlist(): WaitlistEntry[];
  saveWaitlistEntry(entry: WaitlistEntry): void;
  // Reminders
  listReminders(): ReminderJob[];
  saveReminder(reminder: ReminderJob): void;
  // Notifications
  listNotifications(): Notification[];
  saveNotification(notification: Notification): void;
}

// Motor de agenda. El backfill vive en cancel(): libera el slot y devuelve los
// WaitlistEntry candidatos (mismo servicio, ventana que contiene el slot) en orden FIFO.
export interface SchedulerPort {
  getAvailability(serviceId: string, from: Date, to: Date): Slot[];
  book(clientId: string, serviceId: string, start: Date): Appointment; // lanza si solapa
  reschedule(appointmentId: string, newStart: Date): Appointment;
  cancel(appointmentId: string): { freed: Slot; candidates: WaitlistEntry[] };
  dueReminders(now: Date): ReminderJob[];
}

// Salida de avisos. InAppNotifier (feed in-app) ahora; email/SMS/push después.
export interface NotificationPort {
  notify(notification: Notification): void;
  list(): Notification[];
}

import type { Repository } from '../domain/ports';
import type {
  Appointment,
  Client,
  Notification,
  ReminderJob,
  Service,
  WaitlistEntry,
} from '../domain/types';

// Repositorio en memoria para el MVP. Se siembra con datos demo al construirse.
// En Vercel un cold-start lo resetea (aceptable para demo). Swap a DB = fase posterior.
export class InMemoryRepo implements Repository {
  private services = new Map<string, Service>();
  private clients = new Map<string, Client>();
  private appointments = new Map<string, Appointment>();
  private waitlist = new Map<string, WaitlistEntry>();
  private reminders = new Map<string, ReminderJob>();
  private notifications = new Map<string, Notification>();

  constructor(seed = true) {
    if (seed) this.seed();
  }

  // --- Services ---
  listServices(): Service[] {
    return [...this.services.values()];
  }
  getService(id: string): Service | undefined {
    return this.services.get(id);
  }
  saveService(service: Service): void {
    this.services.set(service.id, service);
  }

  // --- Clients ---
  listClients(): Client[] {
    return [...this.clients.values()];
  }
  getClient(id: string): Client | undefined {
    return this.clients.get(id);
  }
  saveClient(client: Client): void {
    this.clients.set(client.id, client);
  }

  // --- Appointments ---
  listAppointments(): Appointment[] {
    return [...this.appointments.values()];
  }
  getAppointment(id: string): Appointment | undefined {
    return this.appointments.get(id);
  }
  saveAppointment(appointment: Appointment): void {
    this.appointments.set(appointment.id, appointment);
  }

  // --- Waitlist ---
  listWaitlist(): WaitlistEntry[] {
    return [...this.waitlist.values()];
  }
  saveWaitlistEntry(entry: WaitlistEntry): void {
    this.waitlist.set(entry.id, entry);
  }

  // --- Reminders ---
  listReminders(): ReminderJob[] {
    return [...this.reminders.values()];
  }
  saveReminder(reminder: ReminderJob): void {
    this.reminders.set(reminder.id, reminder);
  }

  // --- Notifications ---
  listNotifications(): Notification[] {
    return [...this.notifications.values()];
  }
  saveNotification(notification: Notification): void {
    this.notifications.set(notification.id, notification);
  }

  // --- Seed ---
  private seed(): void {
    const services: Service[] = [
      { id: 'svc-bano', name: 'Baño completo', durationMin: 60, priceCents: 2500000, upsells: ['Corte de uñas', 'Limpieza dental'] },
      { id: 'svc-corte', name: 'Corte y peinado', durationMin: 90, priceCents: 3500000, upsells: ['Corte de uñas'] },
      { id: 'svc-spa', name: 'Spa de mascotas', durationMin: 120, priceCents: 5000000, upsells: ['Limpieza dental'] },
    ];
    services.forEach((s) => this.services.set(s.id, s));

    const clients: Client[] = [
      { id: 'cli-ana', name: 'Ana Pérez', phone: '+56911111111' },
      { id: 'cli-bob', name: 'Roberto Díaz', phone: '+56922222222' },
    ];
    clients.forEach((c) => this.clients.set(c.id, c));

    // Una cita futura (mañana 10:00 UTC) para 'svc-bano'.
    const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000);
    tomorrow.setUTCHours(10, 0, 0, 0);
    const apptStart = tomorrow.toISOString();
    const apptEnd = new Date(tomorrow.getTime() + 60 * 60 * 1000).toISOString();
    this.appointments.set('appt-1', {
      id: 'appt-1',
      clientId: 'cli-ana',
      serviceId: 'svc-bano',
      start: apptStart,
      end: apptEnd,
      status: 'booked',
    });

    // Dos en lista de espera para 'svc-bano', cuya ventana cubre ese horario (Bob primero, FIFO).
    const windowStart = new Date(tomorrow.getTime() - 2 * 60 * 60 * 1000).toISOString();
    const windowEnd = new Date(tomorrow.getTime() + 2 * 60 * 60 * 1000).toISOString();
    this.waitlist.set('wl-1', {
      id: 'wl-1', clientId: 'cli-bob', serviceId: 'svc-bano',
      windowStart, windowEnd, createdAt: '2026-05-27T09:00:00.000Z',
    });
    this.waitlist.set('wl-2', {
      id: 'wl-2', clientId: 'cli-ana', serviceId: 'svc-bano',
      windowStart, windowEnd, createdAt: '2026-05-27T09:30:00.000Z',
    });
  }
}

import { InMemoryRepo } from './memoryRepo';
import { MockClock } from './mockClock';
import { Scheduler } from '../engine/scheduler';
import { InAppNotifier } from './inAppNotifier';

// Shared instances for the demo
let sharedRepo: InMemoryRepo | null = null;
let sharedClock: MockClock | null = null;
let sharedScheduler: Scheduler | null = null;
let sharedNotifier: InAppNotifier | null = null;

export function getSharedInstances() {
  if (!sharedRepo) sharedRepo = new InMemoryRepo(true);
  if (!sharedClock) sharedClock = new MockClock();
  if (!sharedScheduler) sharedScheduler = new Scheduler(sharedRepo, sharedClock);
  if (!sharedNotifier) sharedNotifier = new InAppNotifier();

  return {
    repo: sharedRepo,
    clock: sharedClock,
    scheduler: sharedScheduler,
    notifier: sharedNotifier,
  };
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";

interface Appointment {
  id: string;
  clientId: string;
  serviceId: string;
  start: string;
  end: string;
  status: string;
}

interface WaitlistEntry {
  id: string;
  clientId: string;
  serviceId: string;
  windowStart: string;
  windowEnd: string;
  createdAt: string;
}

interface Notification {
  id: string;
  clientId: string;
  kind: string;
  body: string;
  createdAt: string;
}

export default function DashboardPage() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [timeOffset, setTimeOffset] = useState(0); // hours to advance

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [apptsRes, waitRes, notifRes] = await Promise.all([
        fetch("/api/appointments"),
        fetch("/api/waitlist"),
        fetch("/api/notifications"),
      ]);

      if (apptsRes.ok) setAppointments(await apptsRes.json());
      if (waitRes.ok) setWaitlist(await waitRes.json());
      if (notifRes.ok) setNotifications(await notifRes.json());
    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    // Wrap in async function to avoid calling setState directly
    const loadData = async () => {
      await fetchData();
    };
    loadData();
  }, []);

  const handleCancel = async (appointmentId: string) => {
    if (!confirm("¿Cancelar esta cita? El hueco se ofrecerá al primer cliente en lista de espera.")) return;

    try {
      const response = await fetch(`/api/appointments/cancel`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ appointmentId }),
      });

      if (response.ok) {
        alert("Cita cancelada. Se ha ofrecido el hueco al primer cliente en lista de espera.");
        fetchData(); // Refresh all data
      } else {
        alert("Error al cancelar la cita");
      }
    } catch (error) {
      console.error("Cancel error:", error);
      alert("Error al cancelar la cita");
    }
  };

  const handleAdvanceTime = async () => {
    try {
      const response = await fetch("/api/time", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ hours: timeOffset }),
      });

      if (response.ok) {
        alert(`Tiempo avanzado ${timeOffset} horas. Los recordatorios se han actualizado.`);
        fetchData(); // Refresh data
      } else {
        alert("Error al avanzar tiempo");
      }
    } catch (error) {
      console.error("Advance time error:", error);
      alert("Error al avanzar tiempo");
    }
  };

  const formatDate = (iso: string) => {
    const date = new Date(iso);
    return date.toLocaleString("es-ES", {
      weekday: "short",
      day: "numeric",
      month: "short",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getServiceName = (serviceId: string) => {
    switch (serviceId) {
      case "svc-bano": return "Baño completo";
      case "svc-corte": return "Corte y peinado";
      case "svc-spa": return "Spa de mascotas";
      default: return serviceId;
    }
  };

  const getClientName = (clientId: string) => {
    switch (clientId) {
      case "cli-ana": return "Ana Pérez";
      case "cli-bob": return "Roberto Díaz";
      default: return clientId;
    }
  };

  const getNotificationIcon = (kind: string) => {
    switch (kind) {
      case "confirmation": return "✅";
      case "upsell": return "💰";
      case "backfill_offer": return "🔄";
      case "reminder": return "🔔";
      default: return "📢";
    }
  };

  return (
    <div className="min-h-screen bg-zinc-50 text-zinc-900">
      <header className="border-b border-zinc-200 bg-white">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
          <div className="flex items-center gap-2">
            <Link href="/" className="text-lg font-semibold tracking-tight hover:underline">
              🐾 PetDesk
            </Link>
            <span className="text-sm text-zinc-500">/ Panel de groomer</span>
          </div>
          <nav className="flex gap-4 text-sm font-medium">
            <Link href="/" className="rounded-md px-3 py-1.5 text-zinc-700 hover:bg-zinc-100">
              Inicio
            </Link>
            <Link href="/chat" className="rounded-md px-3 py-1.5 text-zinc-700 hover:bg-zinc-100">
              Chat
            </Link>
          </nav>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-6 py-8">
        <div className="mb-8">
          <h1 className="text-2xl font-semibold tracking-tight">Panel de groomer</h1>
          <p className="mt-2 text-zinc-500">Gestiona citas, lista de espera y notificaciones en tiempo real.</p>
        </div>

        {/* Time control */}
        <div className="mb-8 rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
          <h2 className="text-lg font-semibold">⏰ Control de tiempo (demo)</h2>
          <p className="mt-1 text-sm text-zinc-500">Avanza el tiempo para simular recordatorios vencidos.</p>
          <div className="mt-4 flex items-center gap-4">
            <div className="flex-1">
              <label className="mb-1 block text-sm font-medium text-zinc-700">Horas a avanzar</label>
              <input
                type="range"
                min="0"
                max="48"
                value={timeOffset}
                onChange={(e) => setTimeOffset(Number(e.target.value))}
                className="h-2 w-full cursor-pointer appearance-none rounded-lg bg-zinc-200"
              />
              <div className="mt-1 flex justify-between text-xs text-zinc-500">
                <span>0h</span>
                <span className="font-medium">{timeOffset}h</span>
                <span>48h</span>
              </div>
            </div>
            <button
              onClick={handleAdvanceTime}
              className="self-end rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white hover:bg-zinc-800"
            >
              Avanzar tiempo
            </button>
          </div>
        </div>

        {isLoading ? (
          <div className="text-center py-12">
            <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-zinc-300 border-t-zinc-900"></div>
            <p className="mt-3 text-zinc-500">Cargando datos...</p>
          </div>
        ) : (
          <div className="grid gap-8 lg:grid-cols-2">
            {/* Left column: Appointments & Waitlist */}
            <div className="space-y-8">
              {/* Appointments */}
              <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
                <div className="flex items-center justify-between">
                  <h2 className="text-lg font-semibold">📅 Citas del día</h2>
                  <span className="rounded-full bg-zinc-100 px-3 py-1 text-sm font-medium">
                    {appointments.filter((a) => a.status === "booked").length} activas
                  </span>
                </div>
                {appointments.filter((a) => a.status === "booked").length === 0 ? (
                  <p className="mt-4 text-center text-zinc-500">No hay citas programadas para hoy.</p>
                ) : (
                  <div className="mt-4 space-y-4">
                    {appointments
                      .filter((a) => a.status === "booked")
                      .map((appt) => (
                        <div
                          key={appt.id}
                          className="rounded-lg border border-zinc-200 p-4 hover:bg-zinc-50"
                        >
                          <div className="flex items-start justify-between">
                            <div>
                              <div className="font-medium">{getServiceName(appt.serviceId)}</div>
                              <div className="mt-1 text-sm text-zinc-600">
                                Cliente: {getClientName(appt.clientId)}
                              </div>
                              <div className="mt-1 text-sm text-zinc-600">
                                {formatDate(appt.start)} – {formatDate(appt.end).split(" ").pop()}
                              </div>
                            </div>
                            <button
                              onClick={() => handleCancel(appt.id)}
                              className="rounded-md border border-red-300 bg-red-50 px-3 py-1.5 text-sm font-medium text-red-700 hover:bg-red-100"
                            >
                              Cancelar
                            </button>
                          </div>
                        </div>
                      ))}
                  </div>
                )}
              </section>

              {/* Waitlist */}
              <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
                <div className="flex items-center justify-between">
                  <h2 className="text-lg font-semibold">⏳ Lista de espera (FIFO)</h2>
                  <span className="rounded-full bg-zinc-100 px-3 py-1 text-sm font-medium">
                    {waitlist.length} clientes
                  </span>
                </div>
                {waitlist.length === 0 ? (
                  <p className="mt-4 text-center text-zinc-500">La lista de espera está vacía.</p>
                ) : (
                  <div className="mt-4 space-y-4">
                    {waitlist.map((entry, index) => (
                      <div
                        key={entry.id}
                        className="rounded-lg border border-zinc-200 p-4 hover:bg-zinc-50"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-zinc-900 text-xs font-medium text-white">
                              {index + 1}
                            </div>
                            <div>
                              <div className="font-medium">{getClientName(entry.clientId)}</div>
                              <div className="mt-1 text-sm text-zinc-600">
                                Servicio: {getServiceName(entry.serviceId)}
                              </div>
                            </div>
                          </div>
                          <div className="text-right text-sm text-zinc-500">
                            <div>Ventana:</div>
                            <div>{formatDate(entry.windowStart)}</div>
                            <div>a {formatDate(entry.windowEnd).split(" ").pop()}</div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </section>
            </div>

            {/* Right column: Notifications */}
            <div>
              <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
                <div className="flex items-center justify-between">
                  <h2 className="text-lg font-semibold">📢 Feed de notificaciones</h2>
                  <span className="rounded-full bg-zinc-100 px-3 py-1 text-sm font-medium">
                    {notifications.length} notificaciones
                  </span>
                </div>
                {notifications.length === 0 ? (
                  <p className="mt-4 text-center text-zinc-500">No hay notificaciones.</p>
                ) : (
                  <div className="mt-4 space-y-4">
                    {notifications.map((notif) => (
                      <div
                        key={notif.id}
                        className={`rounded-lg border p-4 ${notif.kind === "backfill_offer" ? "border-green-300 bg-green-50" : "border-zinc-200 bg-white"} hover:bg-zinc-50`}
                      >
                        <div className="flex gap-3">
                          <div className="text-xl">{getNotificationIcon(notif.kind)}</div>
                          <div className="flex-1">
                            <div className="flex items-center justify-between">
                              <div className="font-medium">
                                {notif.kind === "confirmation" && "Confirmación de cita"}
                                {notif.kind === "upsell" && "Oferta de upsell"}
                                {notif.kind === "backfill_offer" && "¡Oferta de backfill!"}
                                {notif.kind === "reminder" && "Recordatorio"}
                              </div>
                              <span className="text-xs text-zinc-500">{formatDate(notif.createdAt)}</span>
                            </div>
                            <div className="mt-2 text-sm text-zinc-700">{notif.body}</div>
                            <div className="mt-2 text-xs text-zinc-500">
                              Cliente: {getClientName(notif.clientId)}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </section>

              {/* Stats */}
              <div className="mt-8 grid grid-cols-2 gap-4">
                <div className="rounded-xl border border-zinc-200 bg-white p-5 text-center">
                  <div className="text-2xl font-semibold">
                    {appointments.filter((a) => a.status === "booked").length}
                  </div>
                  <div className="mt-1 text-sm text-zinc-600">Citas activas</div>
                </div>
                <div className="rounded-xl border border-zinc-200 bg-white p-5 text-center">
                  <div className="text-2xl font-semibold">
                    {appointments.filter((a) => a.status === "cancelled").length}
                  </div>
                  <div className="mt-1 text-sm text-zinc-600">Canceladas</div>
                </div>
                <div className="rounded-xl border border-zinc-200 bg-white p-5 text-center">
                  <div className="text-2xl font-semibold">{waitlist.length}</div>
                  <div className="mt-1 text-sm text-zinc-600">En lista de espera</div>
                </div>
                <div className="rounded-xl border border-zinc-200 bg-white p-5 text-center">
                  <div className="text-2xl font-semibold">
                    {notifications.filter((n) => n.kind === "backfill_offer").length}
                  </div>
                  <div className="mt-1 text-sm text-zinc-600">Ofertas de backfill</div>
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="mt-8 rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
          <h2 className="text-lg font-semibold">💡 Cómo funciona el backfill</h2>
          <ol className="mt-3 list-inside list-decimal space-y-2 text-sm text-zinc-600">
            <li>Cuando un cliente cancela una cita, el hueco se libera</li>
            <li>El sistema busca en la lista de espera (FIFO) clientes con el mismo servicio y ventana compatible</li>
            <li>Se notifica automáticamente al primer cliente disponible</li>
            <li>Si acepta, se agienda en el hueco liberado</li>
            <li>¡Tu agenda se mantiene llena incluso con cancelaciones!</li>
          </ol>
          <div className="mt-4">
            <button
              onClick={() => {
                const booked = appointments.filter((a) => a.status === "booked");
                if (booked.length > 0) {
                  handleCancel(booked[0].id);
                } else {
                  alert("No hay citas para cancelar. Primero agenda una desde el chat.");
                }
              }}
              className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white hover:bg-zinc-800"
            >
              Probar cancelación + backfill
            </button>
            <p className="mt-2 text-xs text-zinc-500">
              Cancela una cita para ver el backfill en acción.
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}

