private topServicesBy(appointments: Appointment[], predicate: (a: Appointment) => boolean): ServiceCount[] {
  const counts = new Map<string, number>();
  for (const a of appointments) {
    if (predicate(a)) {
      counts.set(a.serviceId, (counts.get(a.serviceId) ?? 0) + 1);
    }
  }
  return this.toTop5(counts, (id) => id);
}

private topClientsBy(appointments: Appointment[]): ClientCount[] {
  const counts = new Map<string, number>();
  for (const a of appointments) {
    counts.set(a.clientId, (counts.get(a.clientId) ?? 0) + 1);
  }
  return this.toTop5(counts, (id) => id);
}

private toTop5<K>(counts: Map<K, number>, idKey: (k: K) => string): Array<{ id: string; count: number }> {
  const entries = [...counts.entries()];
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return idKey(a[0]) < idKey(b[0]) ? -1 : 1;
  });
  const result: Array<{ id: string; count: number }> = [];
  for (let i = 0; i < Math.min(5, entries.length); i++) {
    result.push({ id: String(entries[i][0]), count: entries[i][1] });
  }
  return result;
}

